function flash(s:string,isError=false){setNotice(isError?"":s);setError(isError?s:"")}
async function submitJob(m:string,p:string,extra:any={}){if(!p.trim()&&m!=="extend")throw new Error("Prompt wajib diisi.");const displayPrompt=extra.displayPrompt;delete extra.displayPrompt;const payload:any={mode:m,prompt:p,...extra};if(["t2v","sfv","i2v","r2v","extend"].includes(m)){payload.model="omni_flash";payload.ratio=Number(ratio);payload.resolution=m==="extend"?1080:Number(resolution);payload.duration=15;}const d=await api("generate",payload);const id=String(d.job_id||"");if(!id)throw new Error(d.tracking_warning||"Provider belum mengembalikan ID tugas. Periksa saldo dan riwayat sebelum mencoba lagi.");const j:Job={id,mode:m,prompt:displayPrompt||p||"Extend video",status:d.status||"queued",created:Date.now(),model:d.model_label||"KAZAMA Video Engine",credit:d.credit_cost,token_reference:d.token_reference};setJobs(x=>[j,...x]);setLastTask(id);setResultKind(m==="music"||m==="tts"?"audio":"video");setResultUrl("");loadCredit();if(d.tracking_warning){flash(d.tracking_warning,true)}else{flash("Permintaan berhasil dikirim! Tugas masuk antrean provider. Kamu bisa melihat progresnya di My Creations.");}}
function motionPrompt(target:"male"|"female"|"both"){
const roles=target==="male"
?"Replace only the original male character with the man from the single uploaded Male reference image. Keep the original female character unchanged."
:target==="female"
?"Replace only the original female character with the woman from the single uploaded Female reference image. Keep the original male character unchanged."
:"Replace the original female character with the woman from Reference Image 1. Replace the original male character with the man from Reference Image 2.";
return roles+"\\n\\n"+MOTION_CONTROL_BASE+"\\n\\nUse the source video as the exact motion and camera reference. Use each uploaded identity photo only for its corresponding character identity. Do not treat identity photos as starting frames. Preserve all source-video actions and timing."
}
async function videoGenerate(){setBusy(true);flash("");try{const files=media;let payload:any={};if(mode==="motion"){if(!files[0])throw new Error("Pilih video referensi gerakan terlebih dahulu.");if(motionTarget==="male"&&!motionMale)throw new Error("Unggah foto Male terlebih dahulu.");if(motionTarget==="female"&&!motionFemale)throw new Error("Unggah foto Female terlebih dahulu.");if(motionTarget==="both")throw new Error("Mode dua orang belum bisa dijalankan: konektor Nexa R2V saat ini hanya menerima 1 video + maksimal 1 foto referensi. Dua foto terpisah belum didukung, jadi KAZAMA tidak akan menggabungkan atau mengirim foto secara keliru.");const identity=motionTarget==="male"?motionMale:motionFemale;payload.media=[await mediaData(files[0]),await mediaData(identity!)];await submitJob("r2v",motionPrompt(motionTarget),{...payload,displayPrompt:"Motion Control · "+(motionTarget==="male"?"Male only":"Female only")+" · Auto prompt"});return;}if(mode==="sfv"||mode==="i2v"){const count=mode==="sfv"?1:3;if(files.length<(mode==="sfv"?1:1)||files.length>count)throw new Error(mode==="sfv"?"Start frame membutuhkan tepat 1 gambar.":"Image-to-Video membutuhkan 1–3 gambar.");payload.media=await Promise.all(files.map(mediaData));}if(mode==="r2v"||mode==="extend"){if(!files[0])throw new Error("Pilih satu video referensi.");payload.media=[await mediaData(files[0])];if(mode==="r2v"&&optImage)payload.media.push(await mediaData(optImage));}await submitJob(mode,prompt,payload)}catch(e){flash(e instanceof Error?e.message:String(e),true)}finally{setBusy(false)}}
async function imageGenerate(){setBusy(true);flash("");try{const imageBody:any={model:imageModel,prompt};if(imageModel.startsWith("gpt_image")||imageModel.startsWith("mai_image"))imageBody.image_size=imageAspect;else{imageBody.aspect=imageAspect;if(!["nano_banana","nano_banana_2_lite"].includes(imageModel))imageBody.resolution=imageSizeKind;}const d=await api("image",imageBody);if(!d.url)throw new Error("KAZAMA tidak mengembalikan URL gambar.");setResultUrl(d.url);setResultKind("image");const j:Job={id:"image-"+Date.now(),mode:"image",prompt,status:"done",created:Date.now(),url:d.url,model:imageModel,credit:d.credit_cost};setJobs(x=>[j,...x]);flash("Gambar berhasil dibuat.")}catch(e){flash(e instanceof Error?e.message:String(e),true)}finally{setBusy(false)}}
async function audioGenerate(kind:"music"|"tts"){setBusy(true);flash("");try{const p=kind==="music"?musicPrompt:ttsText;await submitJob(kind,p,kind==="tts"?{voice:ttsVoice}:{});}catch(e){flash(e instanceof Error?e.message:String(e),true)}finally{setBusy(false)}}
async function makeVoice(){setBusy(true);flash("");try{const selectedVoice=voices.find(v=>v.voice_id===voiceId);const voicePayload:any={text:voiceText,voice_id:voiceId,language_code:language,speed:Number(voiceSpeed)};if(selectedVoice?.features?.stability)voicePayload.stability=Number(stability);if(selectedVoice?.features?.similarityBoost)voicePayload.similarity_boost=Number(similarity);if(selectedVoice?.features?.style)voicePayload.style=Number(style);const d=await api("voice",voicePayload);if(!d.url)throw new Error("URL audio tidak ditemukan.");setResultUrl(d.url);setResultKind("audio");const j:Job={id:"voice-"+Date.now(),mode:"voice",prompt:voiceText,status:"done",created:Date.now(),url:d.url,model:"ElevenLabs Voice"};setJobs(x=>[j,...x]);flash("Voice berhasil dibuat.")}catch(e){flash(e instanceof Error?e.message:String(e),true)}finally{setBusy(false)}}
async function cloneVoice(){setBusy(true);flash("");try{if(!cloneFile)throw new Error("Pilih sampel audio 15–60 detik.");const seconds=await audioDuration(cloneFile);if(seconds<15||seconds>60)throw new Error("Durasi sampel harus 15–60 detik. File ini "+Math.round(seconds)+" detik.");if(cloneFile.size>3*1024*1024)throw new Error("Sampel audio terlalu besar untuk dikirim. Gunakan file sekitar 3 MB atau lebih kecil.");const audio=await dataUrl(cloneFile);const d=await api("voice-clone",{audio,name:cloneName,gender:cloneGender});const id=d.voice?.voice_id||d.voice_id;if(!id)throw new Error("Clone berhasil diproses tetapi voice_id tidak ditemukan.");flash("Voice berhasil dikloning. Voice ID: "+id);loadMeta()}catch(e){flash(e instanceof Error?e.message:String(e),true)}finally{setBusy(false)}}
